def sha(data):
    return hashlib.sha256(data).hexdigest()


def bundle():
    return json.loads(zlib.decompress(base64.b85decode(PAYLOAD)).decode('utf-8'))


def locate():
    fe = Path(__file__).resolve().parent
    root = fe.parent
    be = root / 'Interplex_MES_BE'
    if fe.name != 'Interplex_MES_FE' or not be.is_dir():
        raise RuntimeError('Install updater directly in Interplex_MES_FE alongside Interplex_MES_BE')
    if Path.cwd().resolve() != be.resolve():
        raise RuntimeError('Run from Interplex_MES_BE using python ../Interplex_MES_FE/<updater>.py')
    return root, fe, be


def safe_target(root, rel):
    path = Path(rel)
    if path.is_absolute() or '..' in path.parts or '\\' in rel or not rel.startswith(('Interplex_MES_FE/', 'Interplex_MES_BE/')):
        raise RuntimeError('Rejected unsafe destination path')
    target = root / path
    if target.is_symlink() or (target.exists() and not target.is_file()):
        raise RuntimeError('Refusing symlink or non-file target: ' + rel)
    if not target.resolve().is_relative_to(root.resolve()):
        raise RuntimeError('Path escapes project: ' + rel)
    return target


def config_url(root, be):
    if os.environ.get('DATABASE_URL'):
        return os.environ['DATABASE_URL']
    for location in (be / '.env', be / 'app' / '.env', root / '.env'):
        if not location.is_file():
            continue
        for line in location.read_text(encoding='utf-8-sig').splitlines():
            if re.match(r'^\s*(?:export\s+)?DATABASE_URL\s*=', line):
                value = line.split('=',1)[1].strip()
                if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"',"'"):
                    value = value[1:-1]
                return value
    raise RuntimeError('DATABASE_URL not present in environment or Backend .env')


def check_v0001_schema(root, be, manifest):
    # READ-ONLY audit. Fail closed on connection/metadata errors; never echo DSN, password or raw DBAPI exceptions.
    from sqlalchemy import create_engine, text
    from sqlalchemy.engine import make_url
    url = make_url(config_url(root, be))
    if url.get_backend_name() != 'mssql' or url.get_driver_name() != 'pyodbc':
        raise RuntimeError('Expected mssql+pyodbc connection URL')
    if url.host in ('0.0.0.0','::','[::]'):
        print('[WARN] Client host 0.0.0.0/:: mapped to 127.0.0.1 (local SQL Server only).')
        url = url.set(host='127.0.0.1')
    engine = create_engine(url, pool_pre_ping=True, connect_args={'timeout':7})
    try:
        with engine.connect() as conn:
            db_name = str(conn.execute(text('SELECT DB_NAME()')).scalar())
            meta = conn.execute(text("""
                SELECT t.name AS TableName, c.name AS ColumnName,
                       tp.name AS TypeName, c.precision AS PrecisionValue, c.scale AS ScaleValue
                FROM sys.tables t JOIN sys.schemas s ON t.schema_id=s.schema_id
                JOIN sys.columns c ON c.object_id=t.object_id
                JOIN sys.types tp ON c.user_type_id=tp.user_type_id
                WHERE s.name='dbo' AND t.name IN ('RawMaterialLots','RawMaterialUsage','ModelConfigs')
            """)).mappings().all()
            found = {}
            for row in meta:
                found.setdefault(str(row['TableName']).casefold(),{})[str(row['ColumnName']).casefold()] = dict(row)
            for table, required in manifest['required_db_columns'].items():
                actual = found.get(table.casefold(),{})
                missing = [c for c in required if c.casefold() not in actual]
                if missing:
                    raise RuntimeError(f'V0001 SQL schema mismatch: dbo.{table} missing {missing}')
            for table, qty_col in [('RawMaterialLots','OriginalQty'), ('RawMaterialUsage','ReceivedQty'), ('RawMaterialUsage','RemainderOutQty')]:
                row=found[table.casefold()][qty_col.casefold()]
                if row['TypeName'].casefold() not in ('decimal','numeric') or int(row['PrecisionValue'])!=18 or int(row['ScaleValue'])!=4:
                    raise RuntimeError(f'V0001 SQL schema mismatch: {table}.{qty_col} must be DECIMAL(18,4)')
            indices = conn.execute(text("""
                SELECT t.name AS TableName, i.name AS IndexName, i.is_unique AS IsUnique,
                       i.filter_definition AS FilterDef
                FROM sys.tables t JOIN sys.schemas s ON t.schema_id=s.schema_id
                JOIN sys.indexes i ON i.object_id=t.object_id
                WHERE s.name='dbo' AND t.name IN ('RawMaterialLots','RawMaterialUsage')
            """)).mappings().all()
            index_map = {(str(r['TableName']).casefold(),str(r['IndexName']).casefold()):r for r in indices if r['IndexName']}
            for table, names in manifest['required_indexes'].items():
                for name in names:
                    row=index_map.get((table.casefold(),name.casefold()))
                    if not row or not bool(row['IsUnique']):
                        raise RuntimeError(f'V0001 SQL index missing/non-unique: {table}.{name}')
            for name in ('UX_RawMaterialUsage_OneCurrentPerLot','UX_RawMaterialUsage_NoForkedTransfer'):
                row=index_map[('rawmaterialusage',name.casefold())]
                if not row['FilterDef']:
                    raise RuntimeError(f'V0001 SQL filtered unique index missing predicate: {name}')
            constraints = {str(r[0]).casefold() for r in conn.execute(text("""
                SELECT cc.name FROM sys.check_constraints cc
                UNION ALL SELECT fk.name FROM sys.foreign_keys fk
            """))}
            for table,names in manifest['required_constraints'].items():
                for name in names:
                    if name.casefold() not in constraints:
                        raise RuntimeError(f'V0001 SQL constraint missing: {table}.{name}')
            print(f'[PASS] Read-only SQL schema verification: DB={db_name}, V0001 RAW Lots/Usage columns, unique filters and constraints')
    finally:
        engine.dispose()


def platform_checks(root,be,manifest):
    errors=[]
    if sys.version_info<(3,11) or sys.version_info>=(3,14):
        errors.append('Python must be 3.11–3.13')
    else:print(f'[PASS] Python {sys.version_info.major}.{sys.version_info.minor}.{sys.version_info.micro}')
    for package in ('sqlalchemy','pyodbc'):
        try:__import__(package);print(f'[PASS] Python dependency {package}')
        except ImportError: errors.append('Missing Python dependency '+package)
    try:
        r=subprocess.run(['node','--version'],capture_output=True,text=True,timeout=5)
        if r.returncode!=0: raise RuntimeError()
        v=r.stdout.strip()
        m=re.search(r'v?(\d+)',v)
        if not m or int(m.group(1))<18: raise RuntimeError()
        print('[PASS] Node '+v)
    except Exception: errors.append('Node.js >=18 required')
    for label,repo in (('FE',root/'Interplex_MES_FE'),('BE',be)):
        try:
            r=subprocess.run(['git','-C',str(repo),'branch','--show-current'],capture_output=True,text=True,timeout=5)
            print(f'[INFO] {label} branch: {r.stdout.strip() or "detached/unknown"}')
        except Exception: print(f'[INFO] {label} Git branch not available')
    if all(x not in errors for x in ('Missing Python dependency sqlalchemy','Missing Python dependency pyodbc')):
        try:check_v0001_schema(root,be,manifest)
        except Exception as e:
            # Only declared, safely worded schema mismatches are printed. DBAPI errors may contain login/DSN secrets.
            desc = str(e)
            if not desc.startswith(('V0001 SQL schema mismatch:', 'V0001 SQL index missing',
                                    'V0001 SQL filtered unique', 'V0001 SQL constraint missing:',
                                    'Expected mssql+pyodbc', 'DATABASE_URL not present')):
                desc = 'SQL Server connection/metadata check failed; verify ODBC, credentials and DB availability (details masked)'
            errors.append(desc)
    return errors


def plan(root,payload):
    manifest=payload['manifest']
    edits={};issues=[];already=[];pending=[]
    for rel, hashes in manifest['patches'].items():
        target=safe_target(root,rel)
        body=payload['source'][rel].encode('utf-8')
        if sha(body)!=hashes['after']:
            issues.append('Corrupt bundle: '+rel);continue
        if not target.is_file():
            issues.append('Required source missing: '+rel);continue
        current=target.read_bytes();digest=sha(current)
        if digest==hashes['after']:
            already.append(rel)
        elif digest==hashes['before']:
            pending.append(rel);edits[rel]=body
        else:
            issues.append(f'Source hash mismatch: {rel} (current={digest[:12]}, required={hashes["before"][:12]}). Run source collector and send agent the latest code.')
    for rel, expected in manifest['pinned'].items():
        target=safe_target(root,rel)
        if not target.is_file():issues.append('Phase B required source missing: '+rel)
        elif sha(target.read_bytes())!=expected:
            issues.append('Phase B source hash mismatch: '+rel+' (install/verify Phase B or collect latest)')
        else:print('[PASS] Phase B verified '+rel)
    for rel, expected in manifest['creates'].items():
        target=safe_target(root,rel)
        body=payload['creates'][rel].encode('utf-8')
        if sha(body)!=expected:
            issues.append('Corrupt create bundle: '+rel)
        elif not target.exists():
            pending.append(rel);edits[rel]=body
        elif sha(target.read_bytes())==expected:
            already.append(rel)
        else:
            issues.append('Target already exists with different content: '+rel)
    for rel,append in manifest['appends'].items():
        target=safe_target(root,rel)
        if not target.is_file():
            issues.append('Required Markdown document not found: '+rel);continue
        before=target.read_bytes()
        try: current=before.decode('utf-8')
        except UnicodeDecodeError:
            issues.append('Doc encoding is not UTF-8: '+rel);continue
        marker='<!-- '+RELEASE+' -->'
        if marker in current:
            if current.count(marker)!=1 or append.strip() not in current:
                issues.append('Markdown release marker modified or partial: '+rel)
            else:already.append(rel)
        else:
            new=(current.rstrip('\n')+'\n'+append).encode('utf-8')
            pending.append(rel);edits[rel]=new
    # Reject partial or divergent state rather than masking a previous interrupted release.
    if pending and already:
        issues.append('Partial Phase C installation detected (some targets new, others old); do not apply until reconciled')
    return edits,issues,already,pending


def atomic_write(path,data):
    path.parent.mkdir(parents=True,exist_ok=True)
    with tempfile.NamedTemporaryFile('wb',dir=str(path.parent),prefix='.ipthtmp_',delete=False) as tmp:
        tmp.write(data);tmp.flush();os.fsync(tmp.fileno());name=Path(tmp.name)
    try:os.replace(name,path)
    finally:
        if name.exists():name.unlink()


def apply(root,edits):
    if not edits:
        print('[PASS] Already applied, no file writes')
        return
    # Backup outside FE/BE Git repos and record exactly what was present.
    parent=Path.home()/'.ipth_mes_updater_backups'/RELEASE
    backup=parent/str(time.strftime('%Y%m%dT%H%M%S'))
    if backup.exists():backup=parent/(backup.name+'_'+str(os.getpid()))
    backup.mkdir(parents=True,exist_ok=False)
    record={'release':RELEASE, 'entries':{}}
    written=[]
    try:
        for rel,new in edits.items():
            dest=safe_target(root,rel)
            old=dest.read_bytes() if dest.exists() else None
            if old is not None:
                back=backup/'files'/rel
                back.parent.mkdir(parents=True,exist_ok=True)
                back.write_bytes(old)
            record['entries'][rel]={'existed':old is not None,'before':sha(old) if old is not None else None,'after':sha(new)}
        (backup/'manifest.json').write_text(json.dumps(record,ensure_ascii=False,indent=2),encoding='utf-8')
        for rel,new in edits.items():
            dest=safe_target(root,rel)
            atomic_write(dest,new)
            written.append(rel)
            print('[WRITE] '+rel)
    except Exception:
        for rel in reversed(written):
            dest=safe_target(root,rel)
            entry=record['entries'][rel]
            if entry['existed']:
                atomic_write(dest,(backup/'files'/rel).read_bytes())
            elif dest.is_file():dest.unlink()
        raise
    print('[PASS] Source / documentation installed. Database was not modified.')
    print('Backup: '+str(backup))


def rollback(root):
    parent=Path.home()/'.ipth_mes_updater_backups'/RELEASE
    if not parent.is_dir():raise RuntimeError('No backup directory for this release')
    backups=sorted([d for d in parent.iterdir() if d.is_dir() and (d/'manifest.json').is_file() and not (d/'rolled_back').exists()],reverse=True)
    if not backups: raise RuntimeError('No unapplied backup for rollback')
    backup=backups[0]
    record=json.loads((backup/'manifest.json').read_text(encoding='utf-8'))
    for rel,meta in record['entries'].items():
        dest=safe_target(root,rel)
        if not dest.is_file() or sha(dest.read_bytes())!=meta['after']:
            raise RuntimeError('REJECT rollback: source changed since installation: '+rel)
    for rel,meta in record['entries'].items():
        dest=safe_target(root,rel)
        if meta['existed']:
            old=(backup/'files'/rel).read_bytes()
            if sha(old)!=meta['before']:raise RuntimeError('Backup checksum failed: '+rel)
            atomic_write(dest,old)
        else:dest.unlink()
        print('[RESTORE] '+rel)
    (backup/'rolled_back').write_text('source/doc rollback only; no database rollback\n')
    print('[PASS] Source/docs rolled back. SQL schema and stored RAW data remain untouched.')


def main():
    ap=argparse.ArgumentParser(description='MES2 RAW Phase C updater; run from BE')
    group=ap.add_mutually_exclusive_group(required=True)
    group.add_argument('--scan',action='store_true')
    group.add_argument('--apply',action='store_true')
    group.add_argument('--rollback',action='store_true')
    args=ap.parse_args()
    try:
        root,fe,be=locate()
        if args.rollback:
            rollback(root);return 0
        data=bundle();manifest=data['manifest']
        print('IPTH MES2 RAW Phase C — Scanner / Serial / Remainder (code only)')
        issues=platform_checks(root,be,manifest)
        edits,source_issues,already,pending=plan(root,data)
        issues.extend(source_issues)
        for rel in pending:print('[UPDATE/CREATE] '+rel)
        for rel in already:print('[CURRENT] '+rel)
        print('MARKDOWN: modules/RAW_MATERIAL_PHASE_C.md, changes/2026-11-09-raw-phase-c-v1.md, MODULE_INDEX.md, CHANGELOG.md, SYSTEM_ARCHITECTURE.md')
        if issues:
            for e in issues:print('[REJECT] '+e)
            print('VERDICT: REJECT — no changes permitted. Never force apply.')
            return 2
        print('VERDICT: PASS — required code and V0001 database schema are compatible')
        if args.scan:
            print('SCAN is read-only: zero source/DB writes')
            return 0
        apply(root,edits)
        return 0
    except Exception as e:
        # Avoid reporting DSN/passwords via database exceptions.
        message=str(e)
        if not message.startswith(('Run from Interplex_MES_BE','Install updater','REJECT rollback:', 'No backup directory','No unapplied backup','Source/docs', 'Backup checksum', 'Refusing symlink', 'Path escapes')):
            message=type(e).__name__+' (details masked or incompatible project layout; contact agent)'
        print('VERDICT: REJECT — '+message)
        return 2


if __name__=='__main__':
    raise SystemExit(main())
